'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const {cargoAdditive,lockAdditive,libAdditive,assess,CORE,LOCK,LIB,ROOT}=require('./ci-shared-manifest-route.cjs');
const cargoDiff='@@ -12 +12 @@\n-node-catalog-lab = []\n+node-catalog-lab = ["dep:akula-node-catalog"]\n@@ -100,0 +100 @@\n+akula-node-catalog = { path = "../../modules/node-catalog", optional = true }\n';
const local=new Set(['akula-node-catalog']);
const before='# This file is automatically @generated by Cargo.\nversion = 4\n\n[[package]]\nname = "aquilum-core"\nversion = "0.3.10"\ndependencies = [\n "blake3",\n "serde",\n]\n\n[[package]]\nname = "serde"\nversion = "1.0.0"\nsource = "registry+https://github.com/rust-lang/crates.io-index"\nchecksum = "example"\n';
const after='# This file is automatically @generated by Cargo.\nversion = 4\n\n[[package]]\nname = "akula-node-catalog"\nversion = "0.1.0"\ndependencies = [\n "blake3",\n "serde",\n]\n\n[[package]]\nname = "aquilum-core"\nversion = "0.3.10"\ndependencies = [\n "akula-node-catalog",\n "blake3",\n "serde",\n]\n\n[[package]]\nname = "serde"\nversion = "1.0.0"\nsource = "registry+https://github.com/rust-lang/crates.io-index"\nchecksum = "example"\n';
const base={paths:[CORE,LOCK,'aquilum-app/core/src/node_catalog_lab.rs'],coreDiff:cargoDiff,lockBefore:before,lockAfter:after};
const flags=payload=>assess({...base,...payload});
test('node-catalog opt-in crate does not fan out unrelated OS labs',()=>{
  assert.equal(cargoAdditive(cargoDiff).safe,true);
  assert.equal(lockAdditive(before,after,local),true);
  assert.equal(flags({}).shared_any_risky,false);
});
test('existing dependency and feature changes reactivate impacted lanes',()=>{
  assert.equal(flags({coreDiff:cargoDiff+'+ring = "0.18"\n'}).shared_core_cargo_risky,true);
  assert.equal(flags({lockAfter:after.replace('version = "1.0.0"','version = "1.0.1"')}).shared_lock_risky,true);
});
test('default feature activation and dependency removal fail closed',()=>{
  assert.equal(cargoAdditive('+default = ["node-catalog-lab"]\n-default = []\n').safe,false);
  assert.equal(cargoAdditive('-node-catalog-lab = []\n').safe,false);
});
test('unrelated lock checksum cannot bypass all required OS checks',()=>{
  const x=after.replace('checksum = "example"','checksum = "different"');
  assert.equal(lockAdditive(before,x,local),false);
  assert.equal(flags({lockAfter:x}).shared_lock_risky,true);
});
test('fake local package name, version, or remote source fail closed',()=>{
  assert.equal(lockAdditive(before,after.replace('name = "akula-node-catalog"','name = "surprise"'),local),false);
  assert.equal(lockAdditive(before,after.replace('version = "0.1.0"','version = "9.9.9"'),local),false);
  assert.equal(lockAdditive(before,after.replace('name = "akula-node-catalog"\nversion = "0.1.0"','name = "akula-node-catalog"\nversion = "0.1.0"\nsource = "registry+bad"'),local),false);
});
test('owned source changes rely on own specialized workflow, not all manifest labs',()=>{
  assert.equal(flags({paths:['aquilum-app/core/src/server_installer_fixed_node_lab.rs']}).shared_any_risky,false);
  assert.equal(flags({paths:[CORE,LOCK,'aquilum-app/core/src/server_installer_fixed_node_lab.rs']}).shared_any_risky,false);
});
test('non-additive lib edits risky; additive gated module isolated',()=>{
  assert.equal(flags({paths:[LIB],libDiff:'-pub mod sync;\n'}).shared_core_lib_risky,true);
  const c='+example-probe = []\n',l='+#[cfg(feature = "example-probe")]\n+pub mod example_probe;\n';
  assert.equal(libAdditive(l,cargoAdditive(c).features),true);
  assert.equal(assess({paths:[CORE,LIB],coreDiff:c,libDiff:l}).shared_any_risky,false);
  assert.equal(libAdditive('+pub mod unlocked;\n',cargoAdditive(c).features),false);
});
test('root manifest and direct lock edits always retain previously owned gates',()=>{
  assert.equal(flags({paths:[ROOT]}).shared_root_cargo_risky,true);
  assert.equal(flags({paths:[LOCK]}).shared_lock_risky,true);
});

test('installed-owner OS security is required only for its owned files or a risky Core manifest',()=>{
  const owned=["aquilum-app/core/src/sync/host_install_unix_root.rs","aquilum-app/core/src/sync/host_install_witness.rs","aquilum-app/core/src/sync/mod.rs","aquilum-app/native/Cargo.toml",".github/workflows/sync-installed-os-owner-witness.yml","docs/sync/adr-0038-unix-root-owned-install-receipt.md"];
  for(const file of owned){
    const result=assess({paths:[file]});
    assert.equal(result.installed_owner_owned,true,file);
    assert.equal(result.shared_any_risky,false,file);
  }
  assert.equal(assess({paths:['README.md','aquilum-app/core/src/notion_api_probe.rs']}).installed_owner_owned,false);
  assert.equal(flags({}).installed_owner_owned,false,'optional Core crate does not start OS owner test');
  assert.equal(assess({paths:[CORE],coreDiff:'+ring = "0.18"\n'}).shared_core_cargo_risky,true,'risky Core still routes OS owner');
});
